{"command":"cd /workspace; cat > pinger/src/lib.rs <<'EOF'
//! Spawns the system `ping` binary and turns its output into a stream of results.

use std::fmt;
use std::io::{BufRead, BufReader, Read};
use std::net::IpAddr;
use std::process::{Child, Command, ExitStatus, Stdio};
use std::sync::mpsc::{self, Receiver};
use std::thread;
use std::time::Duration;

/// What the user asked us to ping.
#[derive(Debug, Clone)]
pub enum Target {
    Ip(IpAddr),
    Hostname { domain: String, version: IpVersion },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpVersion {
    Any,
    V4,
    V6,
}

impl Target {
    pub fn new(target: &str, version: IpVersion) -> Target {
        match target.parse::<IpAddr>() {
            Ok(ip) => Target::Ip(ip),
            Err(_) => Target::Hostname {
                domain: target.to_string(),
                version,
            },
        }
    }

    pub fn is_ipv6(&self) -> bool {
        match self {
            Target::Ip(ip) => ip.is_ipv6(),
            Target::Hostname { version, .. } => *version == IpVersion::V6,
        }
    }
}

impl fmt::Display for Target {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Target::Ip(ip) => write!(f, "{ip}"),
            Target::Hostname { domain, .. } => write!(f, "{domain}"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct PingOptions {
    pub target: Target,
    pub interval: Duration,
    pub interface: Option<String>,
    pub raw_arguments: Option<Vec<String>>,
}

impl PingOptions {
    pub fn new(target: &str, interval: Duration, interface: Option<String>) -> Self {
        Self::with_version(target, IpVersion::Any, interval, interface)
    }

    pub fn new_ipv4(target: &str, interval: Duration, interface: Option<String>) -> Self {
        Self::with_version(target, IpVersion::V4, interval, interface)
    }

    pub fn new_ipv6(target: &str, interval: Duration, interface: Option<String>) -> Self {
        Self::with_version(target, IpVersion::V6, interval, interface)
    }

    fn with_version(
        target: &str,
        version: IpVersion,
        interval: Duration,
        interface: Option<String>,
    ) -> Self {
        PingOptions {
            target: Target::new(target, version),
            interval,
            interface,
            raw_arguments: None,
        }
    }

    pub fn with_raw_arguments(mut self, args: Vec<String>) -> Self {
        self.raw_arguments = Some(args);
        self
    }
}

/// A single event coming out of a running ping process.
#[derive(Debug)]
pub enum PingResult {
    Pong(Duration, String),
    Timeout(String),
    Unknown(String),
    PingExited(ExitStatus, String),
}

#[derive(Debug)]
pub enum PingCreationError {
    SpawnError(std::io::Error),
    NotSupported { alternative: String },
    UnknownPing { stdout: Vec<String>, stderr: Vec<String> },
}

impl fmt::Display for PingCreationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PingCreationError::SpawnError(e) => write!(f, "Error spawning ping: {e}"),
            PingCreationError::NotSupported { alternative } => {
                write!(f, "Installed ping is not supported: {alternative}")
            }
            PingCreationError::UnknownPing { stdout, stderr } => {
                write!(f, "Could not detect ping. Stderr: {stderr:?}\nStdout: {stdout:?}")
            }
        }
    }
}

impl std::error::Error for PingCreationError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            PingCreationError::SpawnError(e) => Some(e),
            _ => None,
        }
    }
}

impl From<std::io::Error> for PingCreationError {
    fn from(e: std::io::Error) -> Self {
        PingCreationError::SpawnError(e)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Flavour {
    BusyBox,
    IpUtils,
}

fn first_two_lines(s: &str) -> Vec<String> {
    s.lines().take(2).map(str::to_string).collect()
}

/// Runs `ping -V` to figure out which implementation of ping is installed.
fn detect_flavour() -> Result<Flavour, PingCreationError> {
    let child = Command::new("ping")
        .arg("-V")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    let output = child.wait_with_output()?;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();

    if stderr.contains("BusyBox") {
        Ok(Flavour::BusyBox)
    } else if stdout.contains("iputils") {
        Ok(Flavour::IpUtils)
    } else if stdout.contains("inetutils") {
        Err(PingCreationError::NotSupported {
            alternative: "Please use iputils ping, not inetutils.".to_string(),
        })
    } else {
        Err(PingCreationError::UnknownPing {
            stdout: first_two_lines(&stdout),
            stderr: first_two_lines(&stderr),
        })
    }
}

fn build_command(flavour: Flavour, options: &PingOptions) -> (String, Vec<String>) {
    let program = if options.target.is_ipv6() { "ping6" } else { "ping" };
    let interval = format!("-i{:.1}", options.interval.as_secs_f32());
    let target = options.target.to_string();
    let mut args: Vec<String> = Vec::new();
    match flavour {
        Flavour::IpUtils => {
            args.push("-O".to_string());
            args.push(interval);
            if let Some(iface) = &options.interface {
                args.push("-I".to_string());
                args.push(iface.clone());
            }
            if let Some(raw) = &options.raw_arguments {
                args.extend(raw.iter().cloned());
            }
            args.push(target);
        }
        Flavour::BusyBox => {
            args.push(target);
            args.push(interval);
            if let Some(raw) = &options.raw_arguments {
                args.extend(raw.iter().cloned());
            }
        }
    }
    (program.to_string(), args)
}

/// Case-insensitive ASCII prefix comparison.
fn starts_with_ignore_case(hay: &[u8], needle: &[u8]) -> bool {
    hay.len() >= needle.len() && hay[..needle.len()].eq_ignore_ascii_case(needle)
}

/// Finds `time=<ms>[.<frac>] *ms` (case insensitive) and returns the digits.
fn find_time(line: &str) -> Option<(&str, Option<&str>)> {
    let bytes = line.as_bytes();
    let mut start = 0;
    while start + 5 <= bytes.len() {
        if starts_with_ignore_case(&bytes[start..], b"time=") {
            let mut pos = start + 5;
            let ms_start = pos;
            while pos < bytes.len() && bytes[pos].is_ascii_digit() {
                pos += 1;
            }
            if pos > ms_start {
                let ms = &line[ms_start..pos];
                let mut frac = None;
                if pos + 1 < bytes.len() && bytes[pos] == b'.' && bytes[pos + 1].is_ascii_digit() {
                    let frac_start = pos + 1;
                    let mut p = frac_start;
                    while p < bytes.len() && bytes[p].is_ascii_digit() {
                        p += 1;
                    }
                    frac = Some((frac_start, p));
                }
                let after = frac.map(|(_, end)| end).unwrap_or(pos);
                let mut p = after;
                while p < bytes.len() && bytes[p] == b' ' {
                    p += 1;
                }
                if starts_with_ignore_case(&bytes[p..], b"ms") {
                    return Some((ms, frac.map(|(s, e)| &line[s..e])));
                }
            }
        }
        start += 1;
    }
    None
}

fn parse_pong(line: String) -> Option<PingResult> {
    let (ms, frac) = find_time(&line)?;
    let ms = ms.parse::<u64>().ok()?;
    let ns = match frac {
        None => 0,
        Some(digits) => {
            let count = digits.len() as u32;
            let value = digits.parse::<u64>().ok()?;
            value.wrapping_mul(10u64.wrapping_pow(6u32.wrapping_sub(count)))
        }
    };
    let duration = Duration::from_millis(ms) + Duration::from_nanos(ns);
    Some(PingResult::Pong(duration, line))
}

fn parse_line(line: String) -> Option<PingResult> {
    if line.starts_with("64 bytes from") {
        parse_pong(line)
    } else if line.starts_with("no answer yet") {
        Some(PingResult::Timeout(line))
    } else {
        None
    }
}

fn reader_thread(mut child: Child, tx: mpsc::Sender<PingResult>) {
    let stdout = child.stdout.take().expect("child stdout");
    let reader = BufReader::new(stdout);
    for line in reader.lines() {
        let Ok(line) = line else { break };
        if let Some(result) = parse_line(line) {
            if tx.send(result).is_err() {
                return;
            }
        }
    }
    let mut stderr = String::new();
    if let Some(mut err) = child.stderr.take() {
        let mut raw = Vec::new();
        let _ = err.read_to_end(&mut raw);
        stderr = String::from_utf8_lossy(&raw).into_owned();
    }
    if let Ok(status) = child.wait() {
        let _ = tx.send(PingResult::PingExited(status, stderr));
    }
}

/// Start pinging. Returns a channel that yields parsed results.
pub fn ping(options: PingOptions) -> Result<Receiver<PingResult>, PingCreationError> {
    let flavour = detect_flavour()?;
    let (program, args) = build_command(flavour, &options);
    let child = Command::new(program)
        .args(&args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || reader_thread(child, tx));
    Ok(rx)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pong(line: &str) -> Option<Duration> {
        match parse_line(line.to_string()) {
            Some(PingResult::Pong(d, _)) => Some(d),
            _ => None,
        }
    }

    #[test]
    fn parses_times() {
        assert_eq!(pong("64 bytes from x: time=5 ms"), Some(Duration::from_millis(5)));
        assert_eq!(pong("64 bytes from x: time=7.5ms"), Some(Duration::from_micros(7500)));
        assert_eq!(pong("64 bytes from x: TIME=2 MS"), Some(Duration::from_millis(2)));
        assert_eq!(pong("64 bytes from x: time=3.1234567 ms"), Some(Duration::from_millis(3)));
        assert_eq!(pong("64 bytes from x: time=  3 ms"), None);
        assert_eq!(pong("64 bytes from x: time=.5 ms"), None);
        assert_eq!(pong("100 bytes from x: time=5 ms"), None);
        assert_eq!(pong("64 bytes from x: time=1.5 ms time=2 ms"), Some(Duration::from_micros(1500)));
    }
}
EOF
echo done"}

