        if let Some(name) = self.names.next() {
            let parsed = Color::from_str(name).with_context(|| format!("Invalid color code: `{name}`"));
            if let Ok(color) = &parsed {
                self.used.push(*color);
            }
            return Some(parsed);
        }
        loop {
            let candidate = Color::Indexed(self.next_index);
            self.next_index = self.next_index.wrapping_add(1);
            if !self.used.contains(&candidate) {
                self.used.push(candidate);
                return Some(Ok(candidate));
            }
        }
    }
}
