        x += self.left_label_width(area, !self.y_labels.is_empty());

        let mut axis_x = None;
        if !self.x_labels.is_empty() && y > area.top() {
            axis_x = Some(y);
            y -= 1;
        }

        let mut axis_y = None;
        if !self.y_labels.is_empty() && x + 1 < area.right() {
            axis_y = Some(x);
            x += 1;
        }

        let graph_width = area.right().saturating_sub(x);
        let graph_height = y.saturating_sub(area.top()).saturating_add(1);
        Some(Layout {
            label_x,
            label_y,
            axis_x,
            axis_y,
            graph_area: Rect::new(x, area.top(), graph_width, graph_height),
        })
    }

    fn render_label(buf: &mut Buffer, label: &Line, area: Rect, alignment: Alignment) {
        let line = label.clone().alignment(alignment);
        line.render(area, buf);
    }

    fn render_x_labels(&self, buf: &mut Buffer, layout: &Layout, chart_area: Rect) {
        let Some(y) = layout.label_x else { return };
        let graph_area = layout.graph_area;
        let labels = &self.x_labels;
        let count = labels.len() as u16;
        if count < 2 {
            return;
        }
        let width_between_ticks = graph_area.width / count;

        let first_area = Rect::new(
            chart_area.left(),
            y,
            graph_area.left() - chart_area.left(),
            1,
        );
        Self::render_label(buf, &labels[0], first_area, Alignment::Right);

        for (i, label) in labels[1..labels.len() - 1].iter().enumerate() {
            let x = graph_area.left() + (i + 1) as u16 * width_between_ticks + 1;
            let area = Rect::new(x, y, width_between_ticks.saturating_sub(1), 1);
            Self::render_label(buf, label, area, Alignment::Center);
        }

        let x = graph_area.right() - width_between_ticks;
        let area = Rect::new(x, y, width_between_ticks, 1);
        Self::render_label(buf, &labels[labels.len() - 1], area, Alignment::Right);
    }

    fn render_y_labels(&self, buf: &mut Buffer, layout: &Layout, chart_area: Rect) {
        let Some(x) = layout.label_y else { return };
        let graph_area = layout.graph_area;
        let count = self.y_labels.len() as u16;
        if count < 2 {
            return;
        }
        for (i, label) in self.y_labels.iter().enumerate() {
            let dy = i as u16 * (graph_area.height - 1) / (count - 1);
            if dy < graph_area.bottom() {
                let area = Rect::new(
                    x,
                    graph_area.bottom().saturating_sub(1) - dy,
                    (graph_area.left() - chart_area.left()).saturating_sub(1),
                    1,
                );
                Self::render_label(buf, label, area, Alignment::Left);
            }
        }
    }
}

/// A grid of either braille cells (2x4 dots each) or single dot cells.
struct Grid {
    width: usize,
    height: usize,
    marker: Marker,
    cells: Vec<u16>,
    colors: Vec<Color>,
}

impl Grid {
    fn new(width: u16, height: u16, marker: Marker) -> Self {
        let width = width as usize;
        let height = height as usize;
        let blank = match marker {
            Marker::Braille => BRAILLE_BLANK,
            Marker::Dot => 0,
        };
        Grid {
            width,
            height,
            marker,
            cells: vec![blank; width * height],
            colors: vec![Color::Reset; width * height],
        }
    }

    fn resolution(&self) -> (f64, f64) {
        match self.marker {
            Marker::Braille => (self.width as f64 * 2.0 - 1.0, self.height as f64 * 4.0 - 1.0),
            Marker::Dot => (self.width as f64 - 1.0, self.height as f64 - 1.0),
        }
    }

    fn paint(&mut self, x: usize, y: usize, color: Color) {
        match self.marker {
            Marker::Braille => {
                let index = y / 4 * self.width + x / 2;
                if let Some(c) = self.cells.get_mut(index) {
                    *c |= BRAILLE_DOTS[y % 4][x % 2];
                }
                if let Some(c) = self.colors.get_mut(index) {
                    *c = color;
                }
            }
            Marker::Dot => {
                let index = y * self.width + x;
                if let Some(c) = self.cells.get_mut(index) {
                    *c = 1;
                }
                if let Some(c) = self.colors.get_mut(index) {
                    *c = color;
                }
            }
        }
    }

    fn symbol(&self, index: usize) -> Option<char> {
        let code = self.cells[index];
        match self.marker {
            Marker::Braille if code != BRAILLE_BLANK => char::from_u32(u32::from(code)),
            Marker::Dot if code != 0 => Some(DOT),
            _ => None,
        }
    }
}

struct Painter<'g> {
    grid: &'g mut Grid,
    x_bounds: [f64; 2],
    y_bounds: [f64; 2],
    resolution: (f64, f64),
}

impl Painter<'_> {
    fn get_point(&self, x: f64, y: f64) -> Option<(usize, usize)> {
        let left = self.x_bounds[0];
        let right = self.x_bounds[1];
        let top = self.y_bounds[1];
        let bottom = self.y_bounds[0];
        if x < left || x > right || y < bottom || y > top {
            return None;
        }
        let width = (right - left).abs();
        let height = (top - bottom).abs();
        if width == 0.0 || height == 0.0 {
            return None;
        }
        let x = ((x - left) * self.resolution.0 / width) as usize;
        let y = ((top - y) * self.resolution.1 / height) as usize;
        Some((x, y))
    }

    fn paint(&mut self, x: usize, y: usize, color: Color) {
        self.grid.paint(x, y, color);
    }

    fn point(&mut self, x: f64, y: f64, color: Color) {
        if let Some((x, y)) = self.get_point(x, y) {
            self.paint(x, y, color);
        }
    }

    fn line(&mut self, from: (f64, f64), to: (f64, f64), color: Color) {
        let Some((x1, y1)) = self.get_point(from.0, from.1) else { return };
        let Some((x2, y2)) = self.get_point(to.0, to.1) else { return };
        let dx = x1.abs_diff(x2);
        let dy = y1.abs_diff(y2);
        if dx == 0 {
            for y in y1.min(y2)..=y1.max(y2) {
                self.paint(x1, y, color);
            }
            return;
        }
        if dy == 0 {
            for x in x1.min(x2)..=x1.max(x2) {
                self.paint(x, y1, color);
            }
            return;
        }
        if dy < dx {
            if x1 > x2 {
                self.line_low(x2, y2, x1, y1, color);
            } else {
                self.line_low(x1, y1, x2, y2, color);
            }
        } else if y1 > y2 {
            self.line_high(x2, y2, x1, y1, color);
        } else {
            self.line_high(x1, y1, x2, y2, color);
        }
    }

    fn line_low(&mut self, x1: usize, y1: usize, x2: usize, y2: usize, color: Color) {
        let dx = (x2 - x1) as isize;
        let dy = (y2 as isize - y1 as isize).abs();
        let mut d = 2 * dy - dx;
        let mut y = y1;
        for x in x1..=x2 {
            self.paint(x, y, color);
            if d > 0 {
                y = if y1 > y2 { y.saturating_sub(1) } else { y.saturating_add(1) };
                d -= 2 * dx;
            }
            d += 2 * dy;
        }
    }

    fn line_high(&mut self, x1: usize, y1: usize, x2: usize, y2: usize, color: Color) {
        let dx = (x2 as isize - x1 as isize).abs();
        let dy = (y2 - y1) as isize;
        let mut d = 2 * dx - dy;
        let mut x = x1;
        for y in y1..=y2 {
            self.paint(x, y, color);
            if d > 0 {
                x = if x1 > x2 { x.saturating_sub(1) } else { x.saturating_add(1) };
                d -= 2 * dy;
            }
            d += 2 * dx;
        }
    }
}

impl Widget for Chart<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        let chart_area = area;
        let Some(layout) = self.layout(chart_area) else { return };
        let graph_area = layout.graph_area;

        self.render_x_labels(buf, &layout, chart_area);
        self.render_y_labels(buf, &layout, chart_area);

        if let Some(y) = layout.axis_x {
            for x in graph_area.left()..graph_area.right() {
                buf[(x, y)].set_symbol("─").set_style(self.axis_style);
            }
        }
        if let Some(x) = layout.axis_y {
            for y in graph_area.top()..graph_area.bottom() {
                buf[(x, y)].set_symbol("│").set_style(self.axis_style);
            }
        }
        if let (Some(y), Some(x)) = (layout.axis_x, layout.axis_y) {
            buf[(x, y)].set_symbol("└").set_style(self.axis_style);
        }

        if graph_area.width == 0 || graph_area.height == 0 {
            return;
        }
        buf.set_style(graph_area, Style::default().bg(Color::Reset));

        for series in &self.series {
            let mut grid = Grid::new(graph_area.width, graph_area.height, series.marker);
            let resolution = grid.resolution();
            {
                let mut painter = Painter {
                    grid: &mut grid,
                    x_bounds: self.x_bounds,
                    y_bounds: self.y_bounds,
                    resolution,
                };
                for &(x, y) in series.data {
                    painter.point(x, y, series.color);
                }
                for pair in series.data.windows(2) {
                    painter.line(pair[0], pair[1], series.color);
                }
            }
            for index in 0..grid.cells.len() {
                if let Some(ch) = grid.symbol(index) {
                    let x = (index % grid.width) as u16 + graph_area.left();
                    let y = (index / grid.width) as u16 + graph_area.top();
                    let cell = &mut buf[(x, y)];
                    cell.set_char(ch);
                    let color = grid.colors[index];
                    if color != Color::Reset {
                        cell.set_fg(color);
                    }
                }
            }
        }
    }
}
