//! Samples collected for a single host (or command) and the statistics shown in its header.

use std::time::Duration;

use anyhow::anyhow;
use chrono::Local;
use ratatui_core::style::Style;

use crate::overflow;

pub struct PlotData {
    pub display: String,
    pub data: Vec<(f64, f64)>,
    pub style: Style,
    buffer: chrono::Duration,
    pub simple_graphics: bool,
}

impl PlotData {
    pub fn new(display: String, buffer: u64, style: Style, simple_graphics: bool) -> PlotData {
        PlotData {
            display,
            data: Vec::with_capacity(150),
            style,
            buffer: chrono::Duration::try_seconds(buffer as i64)
                .ok_or_else(|| anyhow!("Error converting {buffer} to seconds"))
                .unwrap(),
            simple_graphics,
        }
    }

    /// Record a new sample (`None` is a timeout / failure) and forget samples that scrolled out.
    pub fn update(&mut self, item: Option<Duration>) {
        let now = Local::now();
        let idx = now.timestamp_millis() as f64 / 1_000f64;
        match item {
            Some(dur) => self.data.push((idx, dur.as_micros() as f64)),
            None => self.data.push((idx, f64::NAN)),
        }
        // Keep the newest sample that is older than the window so the line enters from the edge.
        let earliest = overflow::sub(now, self.buffer).timestamp_millis() as f64 / 1_000f64;
        let last_old = self
            .data
            .iter()
            .enumerate()
            .filter(|(_, (timestamp, _))| *timestamp < earliest)
            .map(|(idx, _)| idx)
            .last();
        if let Some(idx) = last_old {
            self.data.drain(0..idx);
        }
    }

    /// The texts shown in the header row: name, then last/min/max/avg/jitter/p95/timeouts.
    pub fn header_stats(&self) -> Vec<String> {
        let mut columns = vec![self.display.clone()];

        let mut items: Vec<f64> = self
            .data
            .iter()
            .map(|(_, v)| *v)
            .filter(|v| !v.is_nan())
            .collect();
        if items.is_empty() {
            return columns;
        }
        items.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let min = items[0];
        let max = items[items.len() - 1];
        let avg = items.iter().copied().sum::<f64>() / items.len() as f64;
        let jtr = items
            .iter()
            .zip(items.iter().skip(1))
            .map(|(prev, curr)| (curr - prev).abs())
            .sum::<f64>()
            / (items.len() - 1) as f64;

        let percentile_position = 0.95 * items.len() as f32;
        let rounded_position = percentile_position.round() as usize;
        let p95 = items.get(rounded_position).copied().unwrap_or(0f64);

        let timeouts = self.data.iter().filter(|(_, v)| v.is_nan()).count();
        let last = self.data.last().map(|(_, v)| *v).unwrap_or(0f64);

        let fmt = |v: f64| format!("{:?}", Duration::from_micros(v as u64));
        columns.push(format!("last {}", fmt(last)));
        columns.push(format!("min {}", fmt(min)));
        columns.push(format!("max {}", fmt(max)));
        columns.push(format!("avg {}", fmt(avg)));
        columns.push(format!("jtr {}", fmt(jtr)));
        columns.push(format!("p95 {}", fmt(p95)));
        columns.push(format!("t/o {timeouts}"));
        columns
    }
}
