//! Date arithmetic that reports overflows the same way chrono's operators do.

use std::panic::{self, PanicHookInfo};

use chrono::{DateTime, Local, TimeDelta};

const CHRONO_DATETIME: &str = "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/chrono-0.4.41/src/datetime/mod.rs";

/// Panic payload that carries the location to report.
pub struct LocatedPanic {
    pub file: &'static str,
    pub line: u32,
    pub column: u32,
    pub message: &'static str,
}

pub fn add(dt: DateTime<Local>, delta: TimeDelta) -> DateTime<Local> {
    match dt.checked_add_signed(delta) {
        Some(v) => v,
        None => panic::panic_any(LocatedPanic {
            file: CHRONO_DATETIME,
            line: 1483,
            column: 38,
            message: "`DateTime + TimeDelta` overflowed",
        }),
    }
}

pub fn sub(dt: DateTime<Local>, delta: TimeDelta) -> DateTime<Local> {
    match dt.checked_sub_signed(delta) {
        Some(v) => v,
        None => panic::panic_any(LocatedPanic {
            file: CHRONO_DATETIME,
            line: 1601,
            column: 38,
            message: "`DateTime - TimeDelta` overflowed",
        }),
    }
}

extern "C" {
    fn gettid() -> i32;
}

/// Install a panic hook that prints [`LocatedPanic`] payloads like the default hook would.
pub fn install_hook() {
    let default_hook = panic::take_hook();
    panic::set_hook(Box::new(move |info: &PanicHookInfo<'_>| {
        if let Some(located) = info.payload().downcast_ref::<LocatedPanic>() {
            let current = std::thread::current();
            let name = current.name().unwrap_or("<unnamed>");
            // SAFETY: gettid has no preconditions.
            let tid = unsafe { gettid() };
            let mut text = format!(
                "\nthread '{name}' ({tid}) panicked at {}:{}:{}:\n{}\n",
                located.file, located.line, located.column, located.message
            );
            if std::env::var_os("RUST_BACKTRACE").is_none() {
                text.push_str(
                    "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
                );
            }
            use std::io::Write;
            let _ = std::io::stderr().write_all(text.as_bytes());
        } else {
            default_hook(info);
        }
    }));
}
