//! A tiny double buffered terminal writer.
//!
//! Frames are rendered into a [`Buffer`], compared against the previous frame and only the
//! changed cells are written out using plain ANSI escape sequences.

use std::fmt::Write as _;
use std::io::{self, BufWriter, Stdout, Write};

use ratatui_core::buffer::{Buffer, Cell};
use ratatui_core::layout::Rect;
use ratatui_core::style::Color;
use unicode_width::UnicodeWidthStr;

pub struct Screen {
    out: BufWriter<Stdout>,
    buffers: [Buffer; 2],
    current: usize,
    area: Rect,
}

pub fn terminal_area() -> io::Result<Rect> {
    let (width, height) = crossterm::terminal::size()?;
    Ok(Rect::new(0, 0, width, height))
}

fn color_code(color: Color, foreground: bool) -> String {
    let base = if foreground { "38" } else { "48" };
    let indexed = |n: u8| format!("{base};5;{n}");
    match color {
        Color::Reset => if foreground { "39".to_string() } else { "49".to_string() },
        Color::Black => indexed(0),
        Color::Red => indexed(1),
        Color::Green => indexed(2),
        Color::Yellow => indexed(3),
        Color::Blue => indexed(4),
        Color::Magenta => indexed(5),
        Color::Cyan => indexed(6),
        Color::Gray => indexed(7),
        Color::DarkGray => indexed(8),
        Color::LightRed => indexed(9),
        Color::LightGreen => indexed(10),
        Color::LightYellow => indexed(11),
        Color::LightBlue => indexed(12),
        Color::LightMagenta => indexed(13),
        Color::LightCyan => indexed(14),
        Color::White => indexed(15),
        Color::Indexed(n) => indexed(n),
        Color::Rgb(r, g, b) => format!("{base};2;{r};{g};{b}"),
    }
}

/// Cells that changed between two frames, handling multi-width symbols.
fn diff<'a>(previous: &Buffer, next: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
    let mut updates = Vec::new();
    let mut invalidated: usize = 0;
    let mut to_skip: usize = 0;
    let width = next.area.width.max(1) as usize;
    for (i, (current, prev)) in next.content.iter().zip(previous.content.iter()).enumerate() {
        if (current != prev || invalidated > 0) && to_skip == 0 {
            let x = next.area.x + (i % width) as u16;
            let y = next.area.y + (i / width) as u16;
            updates.push((x, y, current));
        }
        let current_width = current.symbol().width();
        to_skip = current_width.saturating_sub(1);
        let affected = current_width.max(prev.symbol().width());
        invalidated = affected.max(invalidated).saturating_sub(1);
    }
    updates
}

impl Screen {
    pub fn new(out: BufWriter<Stdout>) -> io::Result<Self> {
        let area = terminal_area()?;
        Ok(Screen {
            out,
            buffers: [Buffer::empty(area), Buffer::empty(area)],
            current: 0,
            area,
        })
    }

    pub fn raw(&mut self, text: &str) -> io::Result<()> {
        self.out.write_all(text.as_bytes())?;
        self.out.flush()
    }

    pub fn clear(&mut self) -> io::Result<()> {
        self.raw("\x1b[2J")?;
        self.buffers[1 - self.current].reset();
        Ok(())
    }

    fn autoresize(&mut self) -> io::Result<()> {
        let area = terminal_area()?;
        if area != self.area {
            self.buffers[self.current].resize(area);
            self.buffers[1 - self.current].resize(area);
            self.area = area;
            self.clear()?;
        }
        Ok(())
    }

    pub fn draw<F: FnOnce(&mut Buffer, Rect)>(&mut self, render: F) -> io::Result<()> {
        self.autoresize()?;
        let area = self.area;
        render(&mut self.buffers[self.current], area);

        let mut text = String::new();
        {
            let updates = diff(&self.buffers[1 - self.current], &self.buffers[self.current]);
            let mut fg = Color::Reset;
            let mut bg = Color::Reset;
            let mut last: Option<(u16, u16)> = None;
            for (x, y, cell) in updates {
                if !matches!(last, Some((px, py)) if x == px + 1 && y == py) {
                    let _ = write!(text, "\x1b[{};{}H", y + 1, x + 1);
                }
                last = Some((x, y));
                if cell.fg != fg || cell.bg != bg {
                    let _ = write!(text, "\x1b[{};{}m", color_code(cell.fg, true), color_code(cell.bg, false));
                    fg = cell.fg;
                    bg = cell.bg;
                }
                text.push_str(cell.symbol());
            }
        }
        text.push_str("\x1b[39m\x1b[49m\x1b[0m");
        text.push_str("\x1b[?25l");
        self.raw(&text)?;

        self.buffers[1 - self.current].reset();
        self.current = 1 - self.current;
        self.out.flush()
    }
}
EOF
echo ok"}

