fn cli() -> Command {
    let flag = |name: &'static str| Arg::new(name).action(ArgAction::SetTrue);
    let value = |name: &'static str, value_name: &'static str| {
        Arg::new(name).value_name(value_name).action(ArgAction::Set)
    };
