        ))
        .arg(value("watch_interval", "WATCH_INTERVAL").short('n').long("watch-interval")
            .value_parser(value_parser!(f32))
            .help("Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5"))
        .arg(Arg::new("hosts_or_commands").value_name("HOSTS_OR_COMMANDS").num_args(1..)
            .action(ArgAction::Append)
            .help("Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1"))
        .arg(value("buffer", "BUFFER").short('b').long("buffer")
            .value_parser(value_parser!(u64)).default_value("30")
            .help("Determines the number of seconds to display in the graph"))
        .arg(flag("ipv4").short('4').conflicts_with("ipv6")
            .help("Resolve ping targets to IPv4 address"))
        .arg(flag("ipv6").short('6').conflicts_with("ipv4")
            .help("Resolve ping targets to IPv6 address"))
        .arg(value("interface", "INTERFACE").short('i').long("interface")
            .help("Interface to use when pinging"))
        .arg(flag("simple_graphics").short('s').long("simple-graphics"))
        .arg(value("vertical_margin", "VERTICAL_MARGIN").long("vertical-margin")
            .value_parser(value_parser!(u16)).default_value("1")
            .help("Vertical margin around the graph (top and bottom)"))
        .arg(value("horizontal_margin", "HORIZONTAL_MARGIN").long("horizontal-margin")
            .value_parser(value_parser!(u16)).default_value("0")
            .help("Horizontal margin around the graph (left and right)"))
        .arg(Arg::new("color").short('c').long("color").value_name("color")
            .value_delimiter(',').action(ArgAction::Append).help(COLOR_HELP))
        .arg(flag("clear").long("clear")
            .help("Clear the graph from the terminal after closing the program"))
        .arg(Arg::new("ping_args").long("ping-args").value_name("PING_ARGS").num_args(0..)
            .allow_hyphen_values(true).action(ArgAction::Set)
            .help("Extra arguments to pass to `ping`. These are platform dependent"))
