}

fn parse_args() -> Args {
    let m = cli().get_matches();
    Args {
        cmd: m.get_flag("cmd"),
        watch_interval: m.get_one::<f32>("watch_interval").copied(),
        hosts_or_commands: strings(&m, "hosts_or_commands").unwrap_or_default(),
        buffer: *m.get_one::<u64>("buffer").expect("buffer has a default"),
        ipv4: m.get_flag("ipv4"),
        ipv6: m.get_flag("ipv6"),
        interface: m.get_one::<String>("interface").cloned(),
        simple_graphics: m.get_flag("simple_graphics"),
        vertical_margin: *m.get_one::<u16>("vertical_margin").expect("has a default"),
