        ));
    }

    let interval = match args.watch_interval {
        Some(seconds) => Duration::from_millis((seconds * 1000.0) as u64),
        None if args.cmd => Duration::from_millis(500),
        None => Duration::from_millis(200),
    };

    let mut app = App::new(data, args.buffer);
    let (tx, rx) = mpsc::channel();
    let killed = Arc::new(AtomicBool::new(false));
    let mut threads: Vec<JoinHandle<Result<()>>> = vec![];

    if args.cmd {
        for (host_id, cmd) in hosts_or_commands.iter().enumerate() {
            threads.push(start_cmd_thread(cmd, host_id, interval, tx.clone(), killed.clone()));
        }
    } else {
        for (host_id, host) in hosts_or_commands.iter().enumerate() {
            let interface = args.interface.clone();
            let mut options = if args.ipv4 {
                PingOptions::new_ipv4(host, interval, interface)
            } else if args.ipv6 {
                PingOptions::new_ipv6(host, interval, interface)
            } else {
                PingOptions::new(host, interval, interface)
            };
            if let Some(ping_args) = &args.ping_args {
                options = options.with_raw_arguments(ping_args.clone());
            }
            let stream = ping(options)?;
            threads.push(start_ping_thread(host_id, stream, tx.clone(), killed.clone()));
