//! Detection of the installed Linux ping flavour and its command line.

use std::process::{Command, Stdio};

use crate::{PingCreationError, PingOptions};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LinuxPing {
    BusyBox,
    IpUtils,
}

impl LinuxPing {
    /// Runs `ping -V` and inspects what it prints to figure out which ping is installed.
    pub fn detect() -> Result<LinuxPing, PingCreationError> {
        let child = Command::new("ping").arg("-V").stdout(Stdio::piped()).stderr(Stdio::piped()).spawn()?;
        let output = child.wait_with_output()?;
        let stdout = String::from_utf8(output.stdout).expect("Error decoding ping stdout");
        let stderr = String::from_utf8(output.stderr).expect("Error decoding ping stderr");

        if stderr.contains("BusyBox") {
            Ok(LinuxPing::BusyBox)
        } else if stdout.contains("iputils") {
            Ok(LinuxPing::IpUtils)
        } else if stdout.contains("inetutils") {
            Err(PingCreationError::NotSupported {
                alternative: "Please use iputils ping, not inetutils.".to_string(),
            })
        } else {
            Err(PingCreationError::UnknownPing {
                stdout: first_two_lines(&stdout),
                stderr: first_two_lines(&stderr),
            })
        }
    }

    /// The program and arguments used to ping with these options.
    pub fn command(self, options: &PingOptions) -> (String, Vec<String>) {
        let program = if options.target.is_ipv6() { "ping6" } else { "ping" };
        let interval = format!("-i{:.1}", options.interval.as_secs_f32());
        let target = options.target.to_string();
        let raw = options.raw_arguments.iter().flatten().cloned();
        let mut args: Vec<String> = Vec::new();
        match self {
            LinuxPing::IpUtils => {
                args.push("-O".to_string());
                args.push(interval);
                if let Some(interface) = &options.interface {
                    args.push("-I".to_string());
                    args.push(interface.clone());
                }
                args.extend(raw);
                args.push(target);
            }
            LinuxPing::BusyBox => {
                args.push(target);
                args.push(interval);
                args.extend(raw);
            }
        }
        (program.to_string(), args)
    }
}

fn first_two_lines(s: &str) -> Vec<String> {
    s.lines().take(2).map(str::to_string).collect()
}
