//! Spawns the system `ping` binary and turns its output into a stream of results.

mod linux;
mod parser;

use std::fmt;
use std::io::{BufRead, BufReader};
use std::net::IpAddr;
use std::process::{Command, ExitStatus, Stdio};
use std::sync::mpsc::{self, Receiver};
use std::thread;
use std::time::Duration;

use crate::linux::LinuxPing;

/// What the user asked us to ping.
#[derive(Debug, Clone)]
pub enum Target {
    Ip(IpAddr),
    Hostname { domain: String, version: IpVersion },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IpVersion {
    Any,
    V4,
    V6,
}

impl Target {
    pub fn new(target: &str, version: IpVersion) -> Target {
        match target.parse::<IpAddr>() {
            Ok(ip) => Target::Ip(ip),
            Err(_) => Target::Hostname { domain: target.to_string(), version },
        }
    }

    pub fn is_ipv6(&self) -> bool {
        match self {
            Target::Ip(ip) => ip.is_ipv6(),
            Target::Hostname { version, .. } => *version == IpVersion::V6,
        }
    }
}

impl fmt::Display for Target {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Target::Ip(ip) => write!(f, "{ip}"),
            Target::Hostname { domain, .. } => write!(f, "{domain}"),
        }
    }
}

/// Everything needed to start pinging a target.
#[derive(Debug, Clone)]
pub struct PingOptions {
    pub target: Target,
    pub interval: Duration,
    pub interface: Option<String>,
    pub raw_arguments: Option<Vec<String>>,
}

impl PingOptions {
    pub fn new(target: &str, interval: Duration, interface: Option<String>) -> Self {
        Self::with_version(target, IpVersion::Any, interval, interface)
    }

    pub fn new_ipv4(target: &str, interval: Duration, interface: Option<String>) -> Self {
        Self::with_version(target, IpVersion::V4, interval, interface)
    }

    pub fn new_ipv6(target: &str, interval: Duration, interface: Option<String>) -> Self {
        Self::with_version(target, IpVersion::V6, interval, interface)
    }

    fn with_version(target: &str, version: IpVersion, interval: Duration, interface: Option<String>) -> Self {
        PingOptions { target: Target::new(target, version), interval, interface, raw_arguments: None }
    }

    pub fn with_raw_arguments(mut self, args: Vec<String>) -> Self {
        self.raw_arguments = Some(args);
        self
    }
}

/// A single event coming out of a running ping process.
#[derive(Debug)]
pub enum PingResult {
    Pong(Duration, String),
    Timeout(String),
    Unknown(String),
    PingExited(ExitStatus, String),
}

/// Reasons why pinging could not be started.
#[derive(Debug)]
pub enum PingCreationError {
    SpawnError(std::io::Error),
    NotSupported { alternative: String },
    UnknownPing { stdout: Vec<String>, stderr: Vec<String> },
}

impl fmt::Display for PingCreationError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PingCreationError::SpawnError(e) => write!(f, "Error spawning ping: {e}"),
            PingCreationError::NotSupported { alternative } => {
                write!(f, "Installed ping is not supported: {alternative}")
            }
            PingCreationError::UnknownPing { stdout, stderr } => {
                write!(f, "Could not detect ping. Stderr: {stderr:?}\nStdout: {stdout:?}")
            }
        }
    }
}

impl std::error::Error for PingCreationError {
